  };
  const nav = (label) =>
    js(`(() => { const b=[...document.querySelectorAll('nav .nav-item')].find(x=>x.textContent.trim()===${JSON.stringify(label)}); if(!b) throw new Error('no nav ${label}'); b.click(); })()`);
