delete process.env.BENANA_DEV;
delete process.env.BENANA_SCREENSHOT;
const out = path.resolve(__dirname, "../docs/images");
const raw = path.resolve(__dirname, "shots");
fs.mkdirSync(out, { recursive: true });
fs.mkdirSync(raw, { recursive: true });
require("../electron/main.cjs");

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const SELECT = process.env.SHOTS_MOD || "mod_mv3g59vw";
const HERO = "A golden sword that launches any mob it hits into the sky with particles, with a 3 second cooldown.";

app.whenReady().then(async () => {
  await sleep(1500);
  const win = BrowserWindow.getAllWindows()[0];
  win.setContentSize(1600, 1000);
  win.webContents.setBackgroundThrottling(false);
  win.setAlwaysOnTop(true);
  win.show();
  win.focus();
  const js = (e) => win.webContents.executeJavaScript(e);
  const grab = async (file, rect) => {
    for (let i = 0; i < 10; i++) {
      win.webContents.invalidate();
      await sleep(300);
      const img = await win.webContents.capturePage(rect, { stayAwake: true });
      if (!img.isEmpty()) return fs.writeFileSync(file, img.toPNG());
    }
    throw new Error("empty capture " + file);
  };
  const shot = async (name, wait = 1500) => {
    await sleep(wait);
    await grab(path.join(out, `${name}.png`));
    console.log("captured", name);
  };
  const clickText = (sel, text) =>
    js(`(() => { const b=[...document.querySelectorAll(${JSON.stringify(sel)})].find(x=>x.textContent.replace(/\\s+/g,' ').includes(${JSON.stringify(text)})); if(!b) throw new Error('missing ' + ${JSON.stringify(text)}); b.click(); })()`);
  const nav = (label) => clickText("nav .nav-item", label);
  const viewerFrame = () => win.webContents.mainFrame.framesInSubtree.find((f) => f !== win.webContents.mainFrame);
  try {
    await js(`localStorage.setItem('benana.studio.selected', ${JSON.stringify(JSON.stringify(SELECT))}); localStorage.setItem('benana.studio.composing','false'); location.reload();`).catch(() => {});
    await sleep(3000);
    for (let i = 0; i < 240; i++) {
      if (await js(`!!document.querySelector('iframe[title="Bot view"]')`)) break;
      await sleep(1000);
    }
    await sleep(15000);
    // Zoom the orbit camera in on the bot.
    const zoom = Number(process.env.SHOTS_ZOOM || 8);
    await viewerFrame()?.executeJavaScript(`(() => { const c=document.querySelector('canvas'); for (let i=0;i<${zoom};i++) c.dispatchEvent(new WheelEvent('wheel',{deltaY:-120,bubbles:true,cancelable:true})); })()`).catch((e) => console.error("zoom", e.message));
    await sleep(3000);
    const r = await js(`(() => { const b=document.querySelector('.game-view').getBoundingClientRect(); return {x:Math.round(b.x),y:Math.round(b.y),width:Math.round(b.width),height:Math.round(b.height)}; })()`);
    for (let i = 0; i < 12; i++) {
      await grab(path.join(raw, `live-${i}.png`), r);
      if (i % 4 === 0) await grab(path.join(raw, `build-${i}.png`));
      await sleep(700);
    }
    console.log("captured live frames");

    await nav("Mods");
    await shot("mods");
    await nav("Insights");
    await shot("insights");
    await nav("Neatlogs");
    await shot("neatlogs", 2500);
    await clickText(".nl-table tbody tr", "Fixer · Attempt 3");
    await shot("neatlogs-trace", 8000);
    await nav("Entire");
    await clickText(".list-row", "ArrowTracer");
    await shot("entire");

    await nav("Build");
    await clickText("button", "New mod");
    await sleep(1000);
    await js(`(() => { const t=document.querySelector('textarea'); Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'value').set.call(t, ${JSON.stringify(HERO)}); t.dispatchEvent(new Event('input',{bubbles:true})); })()`);
    await shot("new-mod");
  } catch (e) {
    console.error(e);
  } finally {
    await require("../electron/lib/game/index.cjs").stop().catch(() => {});
    app.exit(0);
  }
});
